CREATE OR REPLACE FUNCTION public.can_manage_fitness(_team text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.team_members WHERE user_id=auth.uid() AND public.canonical_team_slug(team_slug)=public.canonical_team_slug(_team) AND lower(role)='coach') OR (public.has_role(auth.uid(),'coach') AND EXISTS(SELECT 1 FROM public.user_age_groups WHERE user_id=auth.uid() AND public.canonical_age_group(age_group)=public.canonical_age_group(_team)))); $$;
CREATE OR REPLACE FUNCTION public.can_view_fitness_player(_player uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.player_registrations p WHERE p.id=_player AND (p.user_id=auth.uid() OR public.can_manage_fitness(replace(lower(p.preferred_age_group),' ','-')) OR EXISTS(SELECT 1 FROM public.guardians g WHERE g.parent_user_id=auth.uid() AND g.status IN ('active','approved','linked') AND public.canonical_age_group(g.team_slug)=public.canonical_age_group(p.preferred_age_group) AND lower(trim(g.player_name))=lower(trim(p.child_name))))); $$;
CREATE OR REPLACE FUNCTION public.can_write_fitness_result(_session uuid,_player uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.fitness_sessions s JOIN public.player_registrations p ON p.id=_player WHERE s.id=_session AND public.canonical_age_group(p.preferred_age_group)=public.canonical_age_group(s.team_slug) AND public.can_manage_fitness(s.team_slug)); $$;
CREATE OR REPLACE FUNCTION public.get_fitness_roster(_team text) RETURNS TABLE(id uuid,child_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.child_name FROM public.player_registrations p WHERE public.canonical_age_group(p.preferred_age_group)=public.canonical_age_group(_team) AND public.can_view_fitness_player(p.id) ORDER BY p.child_name; $$;